contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry used for property checking
    function run(address target, bytes calldata data, uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0) + (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // read Owner before any actions
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // Try withdraw as non-Owner (InvMutTest is not Owner because C was deployed by the checker)
        bool withdrewReverted;
        c.withdraw{value: 0}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        // Try Command as non-Owner, possibly sending ETH
        bool commandReverted;
        c.Command{value: sendAmount}(target, data); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            commandReverted = true;
        } else {
            commandReverted = false;
        }

        // read Owner and balance after attempts
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // General rule asserted: if this contract is not Owner, then both withdraw and Command must revert
        // and C's balance and Owner must remain unchanged. If this contract is Owner then no requirement is enforced here.
        assert( (address(this) == ownerBefore && ownerAfter == ownerBefore) ||
                (address(this) != ownerBefore && withdrewReverted && commandReverted && balAfter == balBefore && ownerAfter == ownerBefore) );
    }

    receive() external payable {}
}

