// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(address target, bytes memory data, uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        address ownerBefore;
        try c.Owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        bool withdrewReverted;
        try c.withdraw{value: 0}() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        bool commandReverted;
        try c.Command{value: sendAmount}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }
        address ownerAfter;
        try c.Owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        uint balAfter = address(c).balance;
        assertTrue((address(this) == ownerBefore && ownerAfter == ownerBefore) ||
                (address(this) != ownerBefore && withdrewReverted && commandReverted && balAfter == balBefore && ownerAfter == ownerBefore));
    }

    function testFuzz_run(address target, bytes memory data, uint256 sendAmount) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, data, sendAmount);
    }

    receive() external payable {}
}
